import React, { useState } from'react';
import axios from 'axios';
import moment from'moment';
import { TextField, Button } from '@react-native-bootstrap-card';

const Bot = () => {
  const [username, setUsername] = useState('');
  const [message, setMessage] = useState('');
  const [tweet, setTweet] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    if (!username ||!message) return;
    setLoading(true);

    try {
      const response = await axios.post(`https://api.twitter.com/1.1/statuses/update.json`, {
        status_message: message,
        status_user: username,
        tweet_timestamp: moment().unix(),
      });
      setTweet(response.data);
      setLoading(false);
    } catch (error) {
      console.error(error);
      setLoading(false);
    }
  };

  return (
    <div align="center">
      <TextField
        label="Username"
        placeholder="@YourAccount"
        onChangeText={setUsername}
      />
      <TextField
        label="Message"
        placeholder="Example: 'This is a terrible tweet!'"
        onChangeText={setMessage}
        value={message}
      />
      <Button variant="primary" color="primary" disabled={loading}>
        {loading? 'Loading...' : 'Submit'}
      </Button>
    </div>
  );
};

export default Bot;
```
